files.~/infra/main.tf:
terraform {
  required_providers {
    google = {
      source = "hashicorp/google"
    }
  }
}

provider "google" {
  project = "my-project"
  region  = var.region
}

variable "region" {
  default = "asia-east1"
}

variable "storage_class" {
  default = "STANDARD"
}

resource "google_storage_bucket" "site" {
  name          = "my-project-tf-site"
  location      = var.region
  storage_class = var.storage_class
  force_destroy = true
}

output "bucket_url" {
  value = google_storage_bucket.site.url
}
